-- 0023: QMK 專案的 MCU 敘述由 STM32F072 更正為 STM32F103（stm32duino bootloader）。
-- 背景：repo 的 cvData 自 2026-07-21 起已是 F103，但唯一含此更正的 0017 被標記「不要跑」
--       （它夾帶了 BitOGuard 的 31 特徵舊內容，會蓋掉 0021/0022 的更正），導致線上至今仍是 F072。
--       本 migration 只碰 qmk-stm32-keyboard 一列，不觸及其他專案。
-- 事實紅線：F103 是「韌體目標推斷」（F103 建置的韌體能運作），不是 dfu-util／讀晶片實測，
--          所以文案寫「現有硬體使用 STM32F103」，不得寫成實測確認。
-- 驗證：2026-09-02 比對確認線上該列 === 0016 寫入的內容（無 admin 手改），故可安全整包覆寫。
-- 冪等：INSERT OR REPLACE 整列。

INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES (
  'qmk-stm32-keyboard',
  '{"id":"qmk-stm32-keyboard","cover":"/images/qmk-stm32-keyboard/numpad-hero.jpg","category":"大學校外作品","title":"開源硬體整合：QMK x STM32 數字鍵盤","period":"2026","description":"整合開源鍵盤 PCB 設計與 QMK/ChibiOS 韌體框架（STM32F103）。實際貢獻：識別開源框架與硬體間的編譯衝突及時序問題，以 LLM 輔助偵錯工具逆向工程 ChibiOS HAL 三件組（chconf/halconf/mcuconf），成功重構設定檔實現完整硬體功能——USB HID 穩定識別、RGB Matrix 運作正常、VIA/VIAL 即時改鍵驗證完成。","tags":["STM32 / Cortex-M","QMK / ChibiOS HAL","USB HID · STM32duino","WS2812B RGB Matrix","EasyEDA Pro"],"detail":{"images":[{"src":"/images/qmk-stm32-keyboard/numpad-top.jpg","caption":"完成品俯視"},{"src":"/images/qmk-stm32-keyboard/numpad-hero.jpg","caption":"與主鍵盤並用"}],"purpose":"市面上 USB 數字鍵盤多為封閉韌體，無法自訂鍵位邏輯、燈效或 Layer 切換；若要深入 QMK 生態，多數教學從 Pro Micro（ATmega32U4）出發，對 STM32 目標的 ChibiOS HAL 配置缺乏中文完整紀錄。\n\n專案範疇說明：本專案以現有開源鍵盤 PCB Layout 為基礎（於 EasyEDA Pro 改版以對接立創商城打板），整合 QMK 開源韌體框架，並非從零設計硬體。核心工程挑戰在於診斷並解決 QMK/ChibiOS 開源框架與 STM32F103 目標硬體之間的編譯失敗與時序衝突問題，並借助 LLM 輔助偵錯工具逆向工程正確的 ChibiOS HAL 配置。\n\n本專案目標是完整走過「從空白 PCB 到可用 USB HID 鍵盤」的全流程，並產出可重現的開源整合紀錄——包含 EasyEDA Pro 工程檔、QMK 韌體原始碼、ChibiOS 三件組配置說明。\n\n具體驗證目標：\n・PCB 設計與立創商城打板全流程\n・STM32F103 搭配 stm32duino bootloader 的韌體燒錄流程\n・QMK + ChibiOS HAL 三件組（chconf / halconf / mcuconf）配置\n・WS2812B RGB Matrix 動畫整合與過流保護設定\n・VIA / VIAL 圖形化改鍵支援","concept":"【核心技術選型決策】\n・STM32F103 vs. Arduino Pro Micro（ATmega32U4）\n  現有硬體使用 STM32F103，QMK 設定採 stm32duino bootloader。這次的重點不是從零選 MCU，而是讓既有硬體、bootloader 與 QMK/ChibiOS 設定能穩定配合。\n\n・ChibiOS vs. 裸機 HAL\n  QMK Firmware 的 STM32 目標使用 ChibiOS 作為硬體抽象層。這次排查的重點是 USB、GPIO 與時鐘設定之間的依賴，而非另寫一套裸機驅動。\n\n・EasyEDA Pro vs. KiCad\n  立創EDA Pro 與立創商城深度整合——選件、DRC 檢查、下單打板在同一平台完成，讓既有開源 PCB 的改版與送廠流程更直接。\n\n【硬體架構】\n・MCU：STM32F103；QMK 設定使用 stm32duino bootloader\n・PCB 使用 EasyEDA Pro（立創EDA）改版，已上傳完整工程檔\n・標準鍵盤矩陣（Matrix Scanning）降低 IO 使用量\n・WS2812B Addressable RGB 實現逐鍵獨立燈效\n・100nF 去耦電容配置於 MCU 電源附近\n\n【韌體架構（QMK + ChibiOS）】\n・chconf.h：ChibiOS kernel 執行緒與 tick 配置\n・halconf.h：啟用所需外設（USB、GPIO、SPI）\n・mcuconf.h：STM32 時鐘、PLL、外設時脈來源設定\n・自定義 LAYOUT_numpad_17 對應 PCB 實體配置\n・模組分離：w17.h（Layout 定義）/ w17.c（RGB Matrix 初始化）/ config.h（硬體參數）/ keymap.c（鍵位邏輯）\n\n【Layer 設計】\n・Layer 0：標準數字鍵盤輸入\n・Layer 1：RGB Matrix 控制（RM_NEXT / RM_PREV / Hue / Sat / Val / 速度）\n・使用 LT() 實現「長按切層、短按輸入」\n\n【RGB 設計】\n・採用 RGB_MATRIX（非舊版 RGBLIGHT），支援動畫模式切換\n・設定 RGB_MATRIX_MAXIMUM_BRIGHTNESS 120 避免過流過熱\n\n【VIA / VIAL 支援】\n・使用者無需重新編譯即可即時調整鍵位與 Layer 配置","outcome":"・完成 17 鍵 USB HID 鍵盤整合流程：EasyEDA Pro PCB 改版 → 立創商城打板 → 手焊組裝 → STM32F103 bootloader 燒錄 → QMK 韌體整合\n・ChibiOS HAL 三件組（chconf / halconf / mcuconf）正確配置，USB HID 穩定識別\n・RGB Matrix 各動畫模式運作正常；RGB_MATRIX_MAXIMUM_BRIGHTNESS 120 限制有效防止 LED 串過流\n・VIA / VIAL 圖形化改鍵驗證通過，Layer 切換與 RGB 控制均可即時調整，無需重新編譯\n・排查並修復 PCB 腳位鏡像問題（EasyEDA 封裝預設 Top/Bottom 層方向差異），為後續 PCB 設計留下可複用的 Checklist\n・完整原始碼已開源於 GitHub，含 EasyEDA 工程檔、QMK 韌體、ChibiOS 配置說明","tech":[{"group":"嵌入式韌體","items":[{"name":"HAL 外設配置","desc":"以 LLM 輔助偵錯工具逆向工程並重構 ChibiOS chconf / halconf / mcuconf 三件組，解決開源 QMK 框架與 STM32F103 硬體間的編譯失敗與時序衝突；正確設定 USB、GPIO 時鐘來源與 PLL，掌握 RTOS tick 與外設初始化順序的依賴關係"},{"name":"鍵盤矩陣掃描","desc":"設計 5×4 ROW2COL 矩陣搭配 5 ms debounce，以最少 IO 支援 17 鍵；理解鬼鍵（ghost key）成因與二極體防護原理"},{"name":"RGB Matrix 驅動","desc":"整合 WS2812B 逐鍵定址，掌握 Hue/Sat/Val 三維色彩控制；設定最大亮度 120 防 USB 過流，理解動畫模式切換與 SPI 時序配置"},{"name":"Layer 與 tap-hold","desc":"以 LT() 實現長按切層、短按輸入，理解 QMK tap-hold 決策窗口（tapping_term）對打字手感的影響與調整方式"}]},{"group":"PCB 設計","items":[{"name":"MCU 外圍電路設計","desc":"在既有開源 PCB 基礎上確認 STM32F103 的 USB 連接、100 nF 去耦電容與燒錄設定；以 EasyEDA Pro 完成改版與送廠資料"}]}],"github":"https://github.com/Jcsk7049/qmk-stm32-keyboard","video":"UQ_tA-CO8Yw"}}',
  '{"id":"qmk-stm32-keyboard","cover":"/images/qmk-stm32-keyboard/numpad-hero.jpg","category":"大學校外作品","title":"Open-Source Hardware Integration: QMK × STM32 Numpad","period":"2026","description":"Integrated an open-source PCB layout with the QMK/ChibiOS firmware framework on STM32F103. Real engineering contribution: identified compilation and timing conflicts between the open-source framework and the hardware, reverse-engineered ChibiOS HAL triple-config (chconf/halconf/mcuconf) with LLM-assisted debugging, and restructured configuration files to achieve 100% hardware functionality — USB HID stable, RGB Matrix operational, VIA/VIAL live keymap verified.","tags":["STM32 / Cortex-M","QMK / ChibiOS HAL","USB HID · STM32duino","WS2812B RGB Matrix","EasyEDA Pro"],"detail":{"images":[{"src":"/images/qmk-stm32-keyboard/numpad-top.jpg","caption":"Completed numpad — top view"},{"src":"/images/qmk-stm32-keyboard/numpad-hero.jpg","caption":"In use alongside main keyboard"}],"purpose":"Most commercial USB numpads run closed firmware with no way to customize key logic, lighting effects, or layer switching. For those entering the QMK ecosystem, most tutorials target Pro Micro (ATmega32U4), with very little documentation on ChibiOS HAL configuration for STM32 targets.\n\nProject scope: This project integrates an existing open-source keyboard PCB layout (adapted in EasyEDA Pro for LCSC ordering) with the QMK open-source firmware framework — it does not design hardware from scratch. The primary engineering challenge was diagnosing and resolving compilation failures and hardware timing conflicts that prevented the open-source QMK/ChibiOS stack from running on the STM32F103 target. LLM-assisted debugging tools were used to reverse-engineer the correct ChibiOS HAL configuration.\n\nThis project aimed to complete the full flow from blank PCB to a working USB HID keyboard, producing a reproducible open-source integration record — including EasyEDA Pro project files, QMK firmware source, and ChibiOS triple-config documentation.\n\nSpecific verification goals:\n- PCB adaptation and LCSC board ordering flow\n- STM32F103 flashing flow using the stm32duino bootloader\n- QMK + ChibiOS HAL triple config (chconf / halconf / mcuconf)\n- WS2812B RGB Matrix animation integration and overcurrent protection\n- VIA / VIAL GUI key remapping support","concept":"[Core Technology Decisions]\n- STM32F103 vs. Arduino Pro Micro (ATmega32U4):\n  The existing hardware uses STM32F103 and the QMK configuration uses the stm32duino bootloader. The work here was not choosing a new MCU from scratch; it was making the existing hardware, bootloader, and QMK/ChibiOS configuration work together reliably.\n\n- ChibiOS vs. Bare-metal HAL:\n  QMK''s STM32 targets use ChibiOS as the hardware abstraction layer. The debugging focused on the dependency between USB, GPIO, and clock settings rather than introducing a separate bare-metal driver.\n\n- EasyEDA Pro vs. KiCad:\n  LCEDA Pro is integrated with LCSC, keeping component selection, DRC, and board ordering in one flow for adapting the existing open-source PCB.\n\n[Hardware Architecture]\n- MCU: STM32F103; QMK uses the stm32duino bootloader\n- PCB adapted in EasyEDA Pro (LCEDA), with full project files uploaded\n- Standard keyboard matrix design to minimize IO usage\n- WS2812B addressable RGB for per-key independent lighting\n- 100nF decoupling capacitors near the MCU supply\n\n[Firmware Architecture — QMK + ChibiOS]\n- chconf.h: ChibiOS kernel thread and tick configuration\n- halconf.h: enable required peripherals (USB, GPIO, SPI)\n- mcuconf.h: STM32 clock, PLL, peripheral clock source settings\n- Custom LAYOUT_numpad_17 mapping to PCB physical layout\n- Module separation: w17.h (layout) / w17.c (RGB Matrix init) / config.h (hardware params) / keymap.c (key logic)\n\n[Layer Design]\n- Layer 0: Standard numpad input\n- Layer 1: RGB Matrix control (RM_NEXT/PREV, Hue/Sat/Val/Speed)\n- LT() for \"hold to switch layer, tap to input\"\n\n[RGB Design]\n- RGB_MATRIX (not legacy RGBLIGHT) for animation mode switching\n- RGB_MATRIX_MAXIMUM_BRIGHTNESS 120 to prevent overcurrent and overheating\n\n[VIA / VIAL Support]\n- Users can remap keys and adjust layers in real time without recompiling","outcome":"- Completed the 17-key USB HID keyboard integration flow: EasyEDA Pro PCB adaptation → LCSC ordering → hand-soldering → STM32F103 bootloader flashing → QMK firmware integration\n- ChibiOS HAL triple config (chconf/halconf/mcuconf) correctly configured; USB HID recognized stably\n- RGB Matrix animation modes all working; RGB_MATRIX_MAXIMUM_BRIGHTNESS 120 effectively prevents LED string overcurrent\n- VIA/VIAL GUI remapping verified; layer switching and RGB control adjustable in real time without recompiling\n- Identified and fixed PCB pin mirror issue (EasyEDA footprint default Top/Bottom layer orientation difference) — reusable checklist for future PCB designs\n- Full source code open-sourced on GitHub: EasyEDA project, QMK firmware, ChibiOS configuration notes","tech":[{"group":"Embedded Firmware","items":[{"name":"HAL Peripheral Configuration","desc":"Reverse-engineered and restructured ChibiOS chconf/halconf/mcuconf triple config using LLM-assisted debugging to resolve compilation failures and timing conflicts between the open-source QMK framework and STM32F103 hardware; correctly set USB, GPIO clock sources, and PLL; understood RTOS tick and peripheral initialization ordering dependencies"},{"name":"Keyboard Matrix Scanning","desc":"Designed 5×4 ROW2COL matrix with 5ms debounce supporting 17 keys on minimal IO; understood ghost key causes and diode protection principles"},{"name":"RGB Matrix Driver","desc":"Integrated WS2812B per-key addressing; Hue/Sat/Val 3D color control; set max brightness 120 to prevent USB overcurrent; understood animation mode switching and SPI timing"},{"name":"Layer & Tap-Hold","desc":"LT() for hold-to-layer, tap-to-input; understanding how QMK tap-hold decision window (tapping_term) affects typing feel and tuning"}]},{"group":"PCB Design","items":[{"name":"MCU Peripheral Circuit","desc":"Verified the STM32F103 USB connection, 100nF decoupling capacitors, and flashing configuration on the existing open-source PCB; completed the adaptation and fabrication files in EasyEDA Pro"}]}],"github":"https://github.com/Jcsk7049/qmk-stm32-keyboard","video":"UQ_tA-CO8Yw"}}',
  6
);
